import{_ as t,o as d,c as o,a2 as c}from"./chunks/framework.CdvW4CUT.js";const u=JSON.parse('{"title":"精灵主题、五态变体与基础 Renderer","description":"","frontmatter":{},"headers":[],"relativePath":"1.21.11/ui/index.md","filePath":"1.21.11/ui/index.md"}'),r={name:"1.21.11/ui/index.md"};function i(a,e,n,s,l,p){return d(),o("div",null,[...e[0]||(e[0]=[c('<h1 id="精灵主题、五态变体与基础-renderer" tabindex="-1">精灵主题、五态变体与基础 Renderer <a class="header-anchor" href="#精灵主题、五态变体与基础-renderer" aria-label="Permalink to &quot;精灵主题、五态变体与基础 Renderer&quot;">​</a></h1><p><code>module.ui</code> 提供了一套不强制绑定 Minecraft 原版固定贴图尺寸的柔性控件渲染库（<code>dev.anvilcraft.lib.v2.ui.flexible</code>），支持根据字符串文本宽度自适应撑开尺寸、深浅配色主题切换、立体/扁平边框风格以及完整的鼠标交互五态变体解析。</p><h2 id="模块信息" tabindex="-1">模块信息 <a class="header-anchor" href="#模块信息" aria-label="Permalink to &quot;模块信息&quot;">​</a></h2><ul><li>模组 ID：<code>anvillib_ui</code>（<code>AnvilLibUi.MODID</code>）</li><li>资源路径生成：<code>AnvilLibUi.location(String path)</code></li></ul><h2 id="精灵体系维度-flexiblesprites" tabindex="-1">精灵体系维度：<code>FlexibleSprites</code> <a class="header-anchor" href="#精灵体系维度-flexiblesprites" aria-label="Permalink to &quot;精灵体系维度：`FlexibleSprites`&quot;">​</a></h2><p><code>FlexibleSprites</code> 将每一个柔性按钮或浮窗的背景九宫格切片按四个正交维度组合寻址：</p><table tabindex="0"><thead><tr><th>维度枚举</th><th>可选枚举值</th><th>切图命名与视觉含义</th></tr></thead><tbody><tr><td><code>SpriteTheme</code></td><td><code>LIGHT(&quot;&quot;)</code>、<code>DARK(&quot;dark&quot;)</code></td><td>亮色（无前缀）或暗色背景风格</td></tr><tr><td><code>SpriteStyle</code></td><td><code>THREE_D(&quot;&quot;)</code>、<code>FLAT(&quot;flat&quot;)</code></td><td>立体凸起边框（无前缀）或现代扁平风格</td></tr><tr><td><code>SpriteType</code></td><td><code>NON_SHADED</code>、<code>SHADED_1PX</code>、<code>SHADED_2PX</code></td><td>控制四边内边距与底边/顶边阴影厚度（按压态将阴影转移到顶边产生下沉感）</td></tr><tr><td><code>SpriteVariant</code></td><td><code>NORMAL(&quot;&quot;)</code>、<code>HIGHLIGHTED</code>、<code>PRESSED</code>、<code>HIGHLIGHTED_PRESSED</code>、<code>HIGHLIGHTED_PRESSING</code></td><td>正常、悬停高亮、已选中、已选中且悬停、悬停并按住交互五态</td></tr></tbody></table><p>辅助静态方法与记录：</p><ul><li><code>FlexibleSprites.pickSprite(SpriteTheme, SpriteStyle, SpriteType, SpriteVariant)</code>：计算实际加载的 <code>SpriteInfo(Identifier sprite, int paddingTop, int paddingBottom, ...)</code>。</li><li><code>FlexibleSprites.pickPointer(SpriteTheme, SpriteStyle, SpriteVariant, PointerDirection)</code>：计算浮窗指针的 <code>PointerSprite(Identifier texture, int width, int height, int pointerUpInset)</code>。</li></ul><h2 id="交互行为机-buttontype-buttoninput" tabindex="-1">交互行为机：<code>ButtonType</code> &amp; <code>ButtonInput</code> <a class="header-anchor" href="#交互行为机-buttontype-buttoninput" aria-label="Permalink to &quot;交互行为机：`ButtonType` &amp; `ButtonInput`&quot;">​</a></h2><p>开发者无需手动组合 <code>if (hovered &amp;&amp; pressed ...)</code>，只需指定 <code>ButtonType</code> 即可将实时鼠标与布尔开关状态映射为 <code>SpriteVariant</code>：</p><div class="language-java vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">public</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> record</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> ButtonInput</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">boolean</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> toggleState, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">boolean</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> hovered, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">boolean</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> pressed, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">boolean</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> startedInBounds) {}</span></span></code></pre></div><table tabindex="0"><thead><tr><th><code>ButtonType</code> 枚举值</th><th>适用控件场景</th><th>五态行为规律</th></tr></thead><tbody><tr><td><code>DISPLAY</code></td><td>纯信息展示面板、标签页角标</td><td>不读取鼠标位置与按压状态，始终返回 <code>NORMAL</code></td></tr><tr><td><code>MOMENTARY</code></td><td>瞬时触发按钮</td><td>悬停返回 <code>HIGHLIGHTED</code>，在控件内部起手按压返回 <code>HIGHLIGHTED_PRESSING</code></td></tr><tr><td><code>TOGGLE</code></td><td>持久化开关 / 选项卡</td><td>读取 <code>toggleState</code> 决定是否处于 <code>PRESSED</code> 或 <code>HIGHLIGHTED_PRESSED</code>，按住反馈 <code>HIGHLIGHTED_PRESSING</code></td></tr><tr><td><code>CLICK</code></td><td>标准点击提交按钮</td><td>兼顾点击过程即时按压与悬停反馈</td></tr></tbody></table><p><code>buttonType.variant(ButtonInput)</code> 返回解析后的 <code>SpriteVariant</code>。</p><h2 id="抽象渲染基类-renderer-t-extends-scope-与-scope" tabindex="-1">抽象渲染基类：<code>Renderer&lt;T extends Scope&gt;</code> 与 <code>Scope</code> <a class="header-anchor" href="#抽象渲染基类-renderer-t-extends-scope-与-scope" aria-label="Permalink to &quot;抽象渲染基类：`Renderer&lt;T extends Scope&gt;` 与 `Scope`&quot;">​</a></h2><p><code>Renderer</code> 保存稳定的外观配置与交互绑定（可在屏幕实例中长期复用，避免每帧重复构造对象）；每次绘制时调用 <code>renderer.open()</code> 开启一个实现 <code>AutoCloseable</code> 的临时 <code>Scope</code> 上下文，设置坐标、字体、文本与鼠标点位后执行 <code>.render()</code>，最后利用 <code>try-with-resources</code> 自动释放本次绘制对 <code>GuiGraphics</code> 等帧对象的引用。</p><h3 id="renderer-t-配置与输入转发-api" tabindex="-1"><code>Renderer&lt;T&gt;</code> 配置与输入转发 API <a class="header-anchor" href="#renderer-t-配置与输入转发-api" aria-label="Permalink to &quot;`Renderer&lt;T&gt;` 配置与输入转发 API&quot;">​</a></h3><table tabindex="0"><thead><tr><th>方法</th><th>说明</th></tr></thead><tbody><tr><td><code>dark()</code></td><td>切换为暗色主题 <code>SpriteTheme.DARK</code></td></tr><tr><td><code>flat()</code></td><td>切换为扁平样式 <code>SpriteStyle.FLAT</code></td></tr><tr><td><code>shaded1px()</code> / <code>shaded2px()</code></td><td>切换边框阴影厚度</td></tr><tr><td><code>highlighted()</code> / <code>pressed()</code> / <code>highlightedPressed()</code> / <code>highlightedPressing()</code></td><td>强制锁定某个静态展示变体（覆盖动态鼠标推导）</td></tr><tr><td><code>buttonType(ButtonType)</code></td><td>指定 <code>ButtonType</code>，与 <code>basedOnMouse(...)</code> 调用顺序无关</td></tr><tr><td><code>toggleState(BooleanSupplier)</code></td><td>绑定 <code>TOGGLE</code> 按钮的外部选中状态供应商，每帧读取</td></tr><tr><td><code>alpha(float alpha)</code></td><td>设置总体透明度 <code>[0.0F, 1.0F]</code>（传入 <code>NaN</code> 时自动忽略保持原值）；控件精灵与文本会直接携带该 alpha 着色</td></tr><tr><td><code>basedOnMouse()</code> / <code>basedOnMouse(IntSet allowedKeys)</code></td><td>开启鼠标驱动的动态五态；不传参数时默认响应左键与右键</td></tr><tr><td><code>onPress(int x, int y)</code> / <code>onPress(Vector2f pos)</code> / <code>onRelease()</code></td><td>在 <code>Screen#mouseClicked(MouseButtonEvent, boolean)</code> 与 <code>Screen#mouseReleased(MouseButtonEvent)</code> 中转发按压起始位置与释放通知，用于准确判断“是否是在控件范围内起手按压”</td></tr><tr><td><code>variantOf(T scope)</code></td><td>查询当前 <code>Scope</code> 状态最终解析出的 <code>SpriteVariant</code></td></tr><tr><td><code>open()</code></td><td>打开一次帧级渲染作用域 <code>T</code></td></tr></tbody></table><h3 id="renderer-scope-常用流式配置方法" tabindex="-1"><code>Renderer.Scope</code> 常用流式配置方法 <a class="header-anchor" href="#renderer-scope-常用流式配置方法" aria-label="Permalink to &quot;`Renderer.Scope` 常用流式配置方法&quot;">​</a></h3><table tabindex="0"><thead><tr><th>方法</th><th>说明</th></tr></thead><tbody><tr><td><code>graphics(GuiGraphics)</code> / <code>font(Font)</code></td><td>传入绘制目标 <code>GuiGraphics</code> 与字体 <code>Font</code></td></tr><tr><td><code>pos(int x, int y)</code> / <code>pos(Vector2i)</code></td><td>设置控件左上角屏幕坐标</td></tr><tr><td><code>mousePos(int x, int y)</code> / <code>mousePos(Vector2f)</code></td><td>设置当前鼠标坐标（当启用非 <code>DISPLAY</code> 的 <code>basedOnMouse</code> 时必填）</td></tr><tr><td><code>size(int width, int height)</code> / <code>size(Vector2i)</code></td><td>固定控件像素宽高</td></tr><tr><td><code>flexSize(int padding)</code> / <code>flexSize(hPad, vPad)</code> / <code>flexSize(left, top, right, bottom)</code></td><td>根据文本宽度和精灵四周阴影内边距自适应计算总大小</td></tr><tr><td><code>literal(String)</code> / <code>translatable(String[, args...])</code> / <code>translatableWithFallback(...)</code> / <code>text(Component)</code></td><td>设置绘制文本</td></tr><tr><td><code>textOffset(int, int)</code> / <code>textOffset(Vector2i)</code></td><td>微调文本绘制位置偏移</td></tr><tr><td><code>contains(@Nullable Vector2f point)</code></td><td>命中检测当前控件矩阵包围盒</td></tr><tr><td><code>render()</code></td><td>提交精灵背景与居中文案绘制</td></tr><tr><td><code>close()</code></td><td>释放作用域内部帧引用</td></tr></tbody></table>',20)])])}const b=t(r,[["render",i]]);export{u as __pageData,b as default};
